  "explain": "📖 교재 근거:\n| 3년 이하 징역 또는 3천만 원 이하 벌금 (징역형과 벌금형 함께 부과 가능) | • 화장품제조업 또는 화장품책임판매업에 필요한 등록과 변경사항 등록을 위반한 자<br>• 맞춤형화장품판매업에 필요한 신고와 변경사항 신고를 위반한 자<br>• 맞춤형화장품조제관리사를 두지 않은 맞춤형화장품판매업자<br>• 기능성화장품에 대한 심사나 보고서 제출, 이에 대한 변경을 위반한 자<br>• 영업금지 조항을 위반한 자<br>• 등록하지 않은 자가 제조한 화장품 또는 제조·수입하여 유통·판매한 자<br>• 화장품 포장 및 기재·표시사항을 훼손(맞춤형화장품 판매를 위하여 필요한 경우 제외), 위·변조한 자 |\n해설: 화장품법상 맞춤형화장품판매업은 신고 대상이므로 지방식품의약품안전청장에게 신고해야 한다는 ②번 설명이 옳습니다. 반면 화장품제조업과 화장품책임판매업은 허가나 단순 신고가 아닌 '등록' 대상이므로 ①, ③, ④번은 틀렸으며, 맞춤형화장품판매업 역시 등록이 아닌 신고 대상이므로 ⑤번은 옳지 않습니다.",
