  "explain": "📖 교재 근거:\n• 내용량이 10mL 초과 50mL 이하 또는 중량이 10g 초과 50g 이하인 화장품에 들어 있는 성분(단, 타르색소, 금박, 샴푸와 린스에 들어 있는 인산염의 종류, 과일산(AHA), 기능성화장품의 효능·효과가 나타나게 하는 원료, 식품의약품안전처장이 사용한도를 고시한 원료는 제외함)\n해설: 근거에 따르면 기재·표시 생략 규정에서도 타르색소, 금박 등은 제외 대상으로 규정되어 있어 반드시 기재해야 하므로 관련 선지(①, ② 등)는 틀린 설명입니다. 반면 ⑤번 정제수는 반드시 표시해야 하는 제외 대상 성분에 포함되지 않으므로 정답입니다.",
