  "explain": "📖 교재 근거:\n| 100만 원 | • 맞춤형화장품조제관리사 또는 이와 유사한 명칭을 사용한 자<br>• 기능성화장품에 대해 제출한 보고서나 심사받은 사항을 변경할 때 변경심사를 받지 않은 자<br>• 동물실험을 실시한 화장품 또는 원료를 사용하여 제조(위탁제조 포함) 또는 수입한 화장품을 유통·판매한 자<br>• 보고와 검사 등의 명령을 위반하여 보고하지 않은 자 |\n해설: 화장품의 판매가격 표시 의무는 화장품의 판매가격을 표시하지 않을 경우 과태료 부과 대상이 되는 판매 주체, 즉 소비자에게 화장품을 직접 판매하는 판매업자(소매업자, 맞춤형화장품판매업자 등)가 수행해야 하므로 ②가 정답입니다. 따라서 화장품제조업자, 화장품책임판매업자, 대한화장품협회, 식품의약품안전처 등은 판매가격 표시의 의무 수행 주체에 해당하지 않습니다.",
