  "derivedFrom": "subject1_q51#1",
  "explain": "📖 법령 근거 (L1092):\n• 화장품책임판매업자가 중요한 유해사례를 알았거나 판매중지나 회수에 준하는 외국정부의 조치 등을 알았을 때에는 15일 이내에 신속보고 해야 하며, 정기보고는 매 반기 종료 후 1개월 이내에 식품의약품안전처장에게 보고 (단, 상시근로자 수가 2인 이하로서 직접 제조한 화장비누만을 판매하는 화장품책임판매업자는 해당 안전성 정보를 보고하지 아니할 수 있음)\n해설: 화장품책임판매업자가 중대(중요)한 유해사례를 알게 되었을 때에는 식품의약품안전처장에게 15일 이내에 신속보고해야 하므로 ④가 정답입니다. 따라서 7일 이내, 3일 이내, 지체 없이 또는 30일 이내로 제시된 선지 ①, ②, ③, ⑤는 옳지 않습니다.",
