  "derivedFrom": "subject1_q60#1",
  "explain": "📖 법령 근거:\n| 「화장품법」(법률) 🎯 기출 | 화장품의 제조·수입·판매 및 수출 등에 관한 사항을 규정함으로써 국민 보건 향상과 화장품 산업의 발전에 기여함을 목적으로 함 |\n⚠️ *인용 위치 자동검증 불가 — 근거가 부정확할 수 있습니다*\n해설: 화장품법 시행규칙상 화장품의 제조번호는 제조업자가 임의로 부여하되 품질추적이 가능한 방식을 적용해야 하므로 ④가 정답입니다. 따라서 제조일자 순 표시, 일련번호나 식약처 지정 번호 체계 등을 규정한 ①, ②, ③, ⑤는 옳지 않습니다.",
