  "explain": "📖 교재 근거:\n| 법령 위계 | 법률(국회) → 시행령(대통령) → 시행규칙(총리령) → 고시(식약처장관). 하위 법령은 상위 법령에 위배 불가. 위반 시 효력 무효. |\n해설: 화장품 관련 법령의 위계는 국회에서 제정하는 법률, 대통령령인 시행령, 총리령인 시행규칙, 식약처장관이 정하는 고시 순으로 구성된다.",
