  "explain": "📖 교재 근거:\n| 10년 이하의 징역 또는 1억 원 이하의 벌금 | • 공공기관의 개인정보 처리업무 방해를 목적으로 개인정보를 변경, 말소하여 업무 수행에 지장을 초래한 자<br>• 거짓이나 그 외 부정한 수단, 방법으로 다른 사람이 처리하고 있는 개인정보를 취득하여 영리 또는 부정한 목적으로 제3자에게 제공, 알선, 교사한 자 |\n해설: 공공기관의 개인정보 처리업무 방해를 목적으로 개인정보를 변경하거나 말소하여 업무 수행에 지장을 초래한 행위는 10년 이하의 징역 또는 1억 원 이하의 벌금에 처해진다. ①과 ③은 5년 이하의 징역 또는 5천만 원 이하의 벌금, ②와 ⑤는 3년 이하의 징역 또는 3천만 원 이하의 벌금에 해당한다.",
