  "explain": "📖 교재 근거:\n| 개인정보처리자 | 업무를 목적으로 개인정보파일을 운용하기 위해 스스로 또는 다른 사람을 통해 개인정보를 처리하는 공공기관, 법인, 단체, 개인 등 |\n해설: 업무를 목적으로 개인정보파일을 운용하기 위해 개인정보를 처리하는 공공기관, 법인, 단체, 개인 등은 '개인정보처리자'에 해당한다. 개인정보취급자는 개인정보처리자의 지휘·감독을 받아 개인정보를 처리하는 업무를 담당하는 임직원, 파견근로자, 시간제근로자 등을 말한다.",
