  "explain": "📖 교재 근거:\n② 설치 금지 장소 불특정 다수가 이용하는 목욕실, 화장실, 발한실, 탈의실 등 개인의 사생활을 현저히 침해할 우려가 있는 장소의 내부를 볼 수 있도록 영상정보처리기기를 설치·운영하는 것을 금지한다. (단, 교도소, 정신보건 시설 등 대통령령으로 정한 시설은 예외이나, 전문가 및 이해관계인 이해 수렴 필요)\n해설: 불특정 다수가 이용하는 목욕실, 화장실 등 사생활 침해 우려 장소의 내부를 볼 수 있도록 영상정보처리기기를 설치·운영하는 것은 금지되나, 교도소, 정신보건 시설 등 대통령령으로 정한 시설은 예외적으로 허용된다.",
