  "statement": "설치 목적 및 장소",
  "truth": false,
  "mode": "answer",
  "sid": "law_st_2cb622",
  "derivedFrom": "subject1_q207#1",
  "explain": "📖 교재 근거:\n③ 영상정보처리기기 설치·운영 안내 🎯 기출 영상정보처리기기를 설치·운영하는 자는 정보주체가 쉽게 인식할 수 있도록 다음 사항이 포함된 안내판을 설치하는 등의 필요한 조치를 취해야 한다.\n• 설치 목적 및 장소\n• 촬영 범위 및 시간\n• 관리책임자 성명 및 연락처\n해설: 영상정보처리기기 안내판의 필수 기재 요소는 '설치 목적 및 장소', '촬영 범위 및 시간', '관리책임자 성명 및 연락처'이다. 영상정보처리기기의 제조사 및 모델명은 필수 기재 사항에 해당하지 않는다.",
